.navbar {
  overflow: hidden;
  background-color: #333;
}
.navbar a {
  float: left;
  padding: 14px 16px;
  text-decoration: none;
  color: white;
}

.subnav-content {
  display: none;
  position: absolute;
  left: 0;
  background-color: red;
  width: 100%;
}
.subnav:hover .subnav-content {
  display: block;
}

.navbar a:hover, .subnav:hover .subnavbtn {
  background-color: red;
}
.subnav-content a:hover {
  background-color: #eee;
  color: black;
}
